package org.eclipse.rdf4j.query.impl;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.common.iteration.AbstractCloseableIteration;
import org.eclipse.rdf4j.common.iteration.CloseableIteratorIteration;
import org.eclipse.rdf4j.model.BNode;
import org.eclipse.rdf4j.model.TripleTerm;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.QueryEvaluationException;
import org.eclipse.rdf4j.query.impl.RemoteBNode.ResponseScope;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class SpilledBindingSetIterationTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@TempDir
	Path directory;

	@Test
	void oneSmallResultDoesNotCreateATemporaryFile() throws Exception {
		MapBindingSet row = new MapBindingSet();
		row.addBinding("value", VF.createLiteral("one"));
		try (var result = SpilledBindingSetIteration
				.materialize(new CloseableIteratorIteration<>(List.<BindingSet>of(row).iterator()), directory)) {
			try (var files = Files.list(directory)) {
				assertThat(files).isEmpty();
			}
			assertThat(result.next()).isEqualTo(row);
			assertThat(result.hasNext()).isFalse();
		}
	}

	@Test
	void snapshotsReusableRowsAndDeletesFileAfterOrderedReplay() {
		List<String> values = List.of("first", "first", "last");
		AtomicInteger index = new AtomicInteger();
		AtomicInteger closed = new AtomicInteger();
		MapBindingSet reusable = new MapBindingSet();
		reusable.addBinding("payload", VF.createLiteral("x".repeat(2 * 1024 * 1024)));
		AbstractCloseableIteration<BindingSet> source = new AbstractCloseableIteration<>() {
			@Override
			public boolean hasNext() {
				return index.get() < values.size();
			}

			@Override
			public BindingSet next() {
				reusable.setBinding("value", VF.createLiteral(values.get(index.getAndIncrement())));
				return reusable;
			}

			@Override
			protected void handleClose() {
				closed.incrementAndGet();
			}
		};

		SpilledBindingSetIteration result = (SpilledBindingSetIteration) SpilledBindingSetIteration
				.materialize(source, directory);
		Path file = result.file();
		assertThat(closed).hasValue(1);
		assertThat(Files.exists(file)).isTrue();
		List<String> replayed = new ArrayList<>();
		while (result.hasNext()) {
			replayed.add(result.next().getValue("value").stringValue());
		}
		assertThat(replayed).containsExactly("first", "first", "last");
		assertThat(Files.exists(file)).isFalse();
	}

	@Test
	void explicitCloseDeletesUnconsumedFile() {
		MapBindingSet row = new MapBindingSet();
		row.addBinding("value", VF.createLiteral("one"));
		row.addBinding("payload", VF.createLiteral("x".repeat(2 * 1024 * 1024)));
		SpilledBindingSetIteration result = (SpilledBindingSetIteration) SpilledBindingSetIteration
				.materialize(new CloseableIteratorIteration<>(List.<BindingSet>of(row).iterator()), directory);
		Path file = result.file();
		assertThat(Files.exists(file)).isTrue();

		result.close();

		assertThat(Files.exists(file)).isFalse();
		assertThat(result.hasNext()).isFalse();
	}

	@Test
	void remoteReadFailureClosesSourceAndDeletesPartialFile() throws Exception {
		QueryEvaluationException failure = new QueryEvaluationException("remote failed after one row");
		AtomicInteger index = new AtomicInteger();
		AtomicInteger closed = new AtomicInteger();
		AbstractCloseableIteration<BindingSet> source = new AbstractCloseableIteration<>() {
			@Override
			public boolean hasNext() {
				if (index.get() > 0) {
					throw failure;
				}
				return true;
			}

			@Override
			public BindingSet next() {
				index.incrementAndGet();
				MapBindingSet row = new MapBindingSet();
				row.addBinding("value", VF.createLiteral("partial"));
				return row;
			}

			@Override
			protected void handleClose() {
				closed.incrementAndGet();
			}
		};

		assertThatThrownBy(() -> SpilledBindingSetIteration.materialize(source, directory)).isSameAs(failure);
		assertThat(closed).hasValue(1);
		try (var files = Files.list(directory)) {
			assertThat(files).isEmpty();
		}
	}

	@Test
	void localSpoolFailureIsDistinguishableFromRemoteFailure() {
		MapBindingSet row = new MapBindingSet();
		row.addBinding("value", VF.createLiteral("one"));
		row.addBinding("payload", VF.createLiteral("x".repeat(2 * 1024 * 1024)));
		Path unavailable = directory.resolve("missing");

		assertThatThrownBy(() -> SpilledBindingSetIteration.materialize(
				new CloseableIteratorIteration<>(List.<BindingSet>of(row).iterator()), unavailable))
						.isInstanceOf(SpilledBindingSetIteration.SpoolFailure.class)
						.hasMessageContaining("Could not spool SERVICE result");
	}

	@Test
	void nestedTripleBlankNodesRetainRemoteIdentityAcrossReplay() {
		Object epoch = new Object();
		ResponseScope response = RemoteBNode.newResponseScope(new BlankNodeAllocationScope(), VF, epoch, true);
		BNode remote = (BNode) response.map(VF.createBNode("remote"));
		TripleTerm nested = VF.createTripleTerm(VF.createIRI("urn:inner"), VF.createIRI("urn:predicate"), remote);
		TripleTerm outer = VF.createTripleTerm(remote, VF.createIRI("urn:predicate"), nested);
		MapBindingSet row = new MapBindingSet();
		row.addBinding("triple", outer);

		try (var result = SpilledBindingSetIteration
				.materialize(new CloseableIteratorIteration<>(List.<BindingSet>of(row).iterator()), directory)) {
			assertThat(result.hasNext()).isTrue();
			TripleTerm restored = (TripleTerm) result.next().getValue("triple");
			BNode subject = (BNode) restored.getSubject();
			BNode object = (BNode) ((TripleTerm) restored.getObject()).getObject();
			assertThat(RemoteBNode.sameTrustedIdentity((RemoteBNode) subject, (RemoteBNode) object)).isTrue();
			assertThat(RemoteBNode.toRemoteValue(subject, epoch, true, true)).isEqualTo(VF.createBNode("remote"));
			assertThat(result.hasNext()).isFalse();
		}
	}
}
